const { useEffect, useRef, useState } = React;

// 画布框架：按 DPR 设置像素尺寸、跟随宽度重绘、切换主题时重绘；坐标单位为 CSS 像素
const useCanvas = (draw, deps) => {
  const ref = useRef(null);
  const { color } = useTokens();
  // 重绘函数每次渲染更新，尺寸监听只建立一次，动画逐帧重绘时不重复创建观察器
  const renderRef = useRef(() => {});
  renderRef.current = () => {
    const canvas = ref.current;
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx) return;
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = canvas.getBoundingClientRect();
    const pixelWidth = Math.round(width * dpr);
    const pixelHeight = Math.round(height * dpr);
    // 重设尺寸会清空并重新分配画布，只在尺寸真正变化时才做
    if (canvas.width !== pixelWidth || canvas.height !== pixelHeight) {
      canvas.width = pixelWidth;
      canvas.height = pixelHeight;
    }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);
    ctx.save();
    draw(ctx, { width, height, dpr, color });
    ctx.restore();
  };
  useEffect(() => renderRef.current(), [color, ...deps]);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const observer = new ResizeObserver(() => renderRef.current());
    observer.observe(canvas);
    return () => observer.disconnect();
  }, []);
  return ref;
};

// 画布上的标注文字：等宽字体、次要墨色
const note = (ctx, color, text, x, y, align = "left") => {
  ctx.save();
  ctx.font = `12px ${color("font-mono")}`;
  ctx.fillStyle = color("ink-3");
  ctx.textAlign = align;
  ctx.textBaseline = "middle";
  ctx.fillText(text, x, y);
  ctx.restore();
};

const KIT_STYLE = `
  @scope {
    .cb-grid {
      background-image: radial-gradient(var(--tau-line-1) 1px, transparent 1px);
      background-size: 20px 20px;
      background-position: 10px 10px;
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Stage = ({ canvasRef, height, className = "" }) => (
  <canvas
    ref={canvasRef}
    className={`cb-grid block w-full rounded-tau-md border border-line-1 ${className}`}
    style={{ height }}
  />
);

const Chip = ({ children }) => (
  <code className="rounded-tau-sm bg-hover px-1.5 py-0.5 font-tau-mono text-tau-sm text-ink-2">{children}</code>
);

const Slider = ({ label, value, min, max, step = 1, onChange, format = value => value }) => (
  <label className="flex min-w-[220px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      onChange={event => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{format(value)}</span>
  </label>
);

const Demo = ({ children }) => (
  <div className="flex flex-col gap-3">
    <style>{KIT_STYLE}</style>
    {children}
  </div>
);

const Row = ({ children }) => <div className="flex flex-wrap items-center gap-x-6 gap-y-3">{children}</div>;

const Component = () => {
  const recorderRef = useRef(null);
  const chunksRef = useRef([]);
  const ballsRef = useRef(null);
  const [recording, setRecording] = useState(false);
  const [videoUrl, setVideoUrl] = useState(null);
  const [tick, setTick] = useState(0);

  // 持续推进动画帧
  useEffect(() => {
    let frame = 0;
    const loop = () => {
      setTick(value => value + 1);
      frame = requestAnimationFrame(loop);
    };
    frame = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frame);
  }, []);

  useEffect(() => () => videoUrl && URL.revokeObjectURL(videoUrl), [videoUrl]);

  const ref = useCanvas((ctx, { width, height, color }) => {
    if (!ballsRef.current) {
      ballsRef.current = Array.from({ length: 12 }, (_, index) => ({
        x: Math.random() * width,
        y: Math.random() * height,
        r: 8 + Math.random() * 14,
        vx: (Math.random() - 0.5) * 3,
        vy: (Math.random() - 0.5) * 3,
        token: `tag-${(index % 5) + 1}`,
      }));
    }
    // 录制的是画布像素，背景要画进去，否则视频里是透明底
    ctx.fillStyle = color("bg-surface");
    ctx.fillRect(0, 0, width, height);
    for (const ball of ballsRef.current) {
      ball.x += ball.vx;
      ball.y += ball.vy;
      if (ball.x - ball.r < 0 || ball.x + ball.r > width) ball.vx *= -1;
      if (ball.y - ball.r < 0 || ball.y + ball.r > height) ball.vy *= -1;
      ctx.beginPath();
      ctx.arc(ball.x, ball.y, ball.r, 0, Math.PI * 2);
      ctx.fillStyle = color(ball.token);
      ctx.fill();
    }
  }, [tick]);

  const start = () => {
    setVideoUrl(null);
    chunksRef.current = [];
    const stream = ref.current.captureStream(30);
    const recorder = new MediaRecorder(stream, { mimeType: "video/webm" });
    recorder.ondataavailable = event => event.data.size > 0 && chunksRef.current.push(event.data);
    recorder.onstop = () => setVideoUrl(URL.createObjectURL(new Blob(chunksRef.current, { type: "video/webm" })));
    recorder.start();
    recorderRef.current = recorder;
    setRecording(true);
  };

  const stop = () => {
    recorderRef.current?.stop();
    setRecording(false);
  };

  useEffect(() => () => recorderRef.current?.state === "recording" && recorderRef.current.stop(), []);

  return (
    <Demo>
      <Stage canvasRef={ref} height={240} />
      <Row>
        {recording ? (
          <ui.Button variant="danger-soft" size="sm" icon={icons.Square} onClick={stop}>
            停止录制
          </ui.Button>
        ) : (
          <ui.Button variant="secondary" size="sm" icon={icons.Video} onClick={start}>
            开始录制
          </ui.Button>
        )}
        {recording && <ui.Tag color="red">录制中</ui.Tag>}
        <Chip>canvas.captureStream(30)</Chip>
      </Row>
      {videoUrl && (
        <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
          <span className="text-tau-sm text-ink-3">录制结果</span>
          <video src={videoUrl} controls className="max-h-[220px] w-full rounded-tau-sm" />
          <a href={videoUrl} download="canvas-recording.webm" className="self-start text-tau-body text-accent-text hover:underline">
            下载视频
          </a>
        </div>
      )}
    </Demo>
  );
};

